def otherside_rightangle(w, h):
    """
    Calculate the length of the third side of a right-angled triangle given two sides.

    Args:
        w (float): Length of one side.
        h (float): Length of the other side.

    Returns:
        float: Length of the hypotenuse if w and h are the legs, or the length of the remaining leg
               if one of the inputs is the hypotenuse.
