    # Check if the inputs are the legs (w^2 + h^2)
    if w ** 2 + h ** 2 > max(w, h) ** 2:
        return math.sqrt(w ** 2 + h ** 2)
    else:
        # If one of the inputs is the hypotenuse, calculate the other leg
        if w > h:
            return math.sqrt(w ** 2 - h ** 2)
        else:
            return math.sqrt(h ** 2 - w ** 2)
